import re
from pathlib import Path

import pytest

from hp437b.commands import COMMANDS, encode
from hp437b.errors import CapabilityUnavailable

# Independent literal cases; values and expected bytes are not generated by the encoder.
ARGUMENTS = {
    "CL": ("98.5", b"CL98.5EN"),
    "KB": ("99.9", b"KB99.9EN"),
    "DY": ("0.001", b"DY0.001EN"),
    "OS": ("-99.99", b"OS-99.99EN"),
    "LH": ("299.999", b"LH299.999EN"),
    "LL": ("-299.999", b"LL-299.999EN"),
    "RC": (0, b"RC0EN"),
    "ST": (10, b"ST10EN"),
    "RE": (3, b"RE3EN"),
    "RM": (5, b"RM5EN"),
    "SE": (9, b"SE9EN"),
    "FM": (128, b"FM128EN"),
    "FR": ("0.3", b"FR0.3GZ"),
    "HZ": (100000, b"100000HZ"),
    "KZ": (100, b"100KZ"),
    "MZ": ("0.1", b"0.1MZ"),
    "GZ": ("0.0001", b"0.0001GZ"),
    "*SRE": (4, b"*SRE4"),
    "*ESE": (32, b"*ESE32"),
    "DU": ("CONNECT DUT", b"DUCONNECT DUT"),
    "%": ("98.5", b"98.5%"),
    "PCT": ("98.5", b"98.5PCT"),
}
LITERALS = {
    "*CLS": b"*CLS",
    "CS": b"CS",
    "DA": b"DA",
    "DC0": b"DC0",
    "DC1": b"DC1",
    "DD": b"DD",
    "DE": b"DE",
    "DN": b"DN",
    "LT": b"LT",
    "RT": b"RT",
    "UP": b"UP",
    "EN": b"EN",
    "ERR?": b"ERR?",
    "*ESR?": b"*ESR?",
    "*ESE?": b"*ESE?",
    "EX": b"EX",
    "FA": b"FA",
    "FH": b"FH",
    "GT0": b"GT0",
    "GT1": b"GT1",
    "GT2": b"GT2",
    "*IDN?": b"*IDN?",
    "LG": b"LG",
    "LN": b"LN",
    "LM0": b"LM0",
    "LM1": b"LM1",
    "LP2": b"LP2",
    "OC0": b"OC0",
    "OC1": b"OC1",
    "OD": b"OD",
    "OF0": b"OF0",
    "OF1": b"OF1",
    "PR": b"PR",
    "RA": b"RA",
    "RH": b"RH",
    "RL0": b"RL0",
    "RL1": b"RL1",
    "RL2": b"RL2",
    "SM": b"SM",
    "*SRE?": b"*SRE?",
    "*STB?": b"*STB?",
    "TR0": b"TR0",
    "TR1": b"TR1",
    "TR2": b"TR2",
    "TR3": b"TR3",
    "ZE": b"ZE",
}
RF_CASES = {f"RF{n}": ("98.5", f"RF{n}98.5%".encode()) for n in range(10)}


@pytest.mark.parametrize("code,case", list(ARGUMENTS.items()) + list(RF_CASES.items()))
def test_parameter_wire_cases(code, case):
    value, wire = case
    assert encode(code, value) == wire


@pytest.mark.parametrize("code,wire", LITERALS.items())
def test_literal_wire_cases(code, wire):
    assert encode(code) == wire


@pytest.mark.parametrize("code", [code for code, spec in COMMANDS.items() if spec.deferred])
def test_every_deferred_command_guard(code):
    with pytest.raises(CapabilityUnavailable, match="A0"):
        encode(code, "INJECT;PR")


@pytest.mark.parametrize(
    "code,value",
    [
        ("CL", 120.1),
        ("KB", 0.9),
        ("DY", 100),
        ("OS", 100),
        ("RC", 11),
        ("ST", 0),
        ("RE", 4),
        ("RM", -1),
        ("SE", 10),
        ("FM", 3),
        ("*ESE", 1),
        ("*SRE", 256),
        ("DU", "OK;PR"),
        ("DU", "a"),
        ("RF0", 150),
        ("LG", 1),
        ("FR", "0.00001"),
        ("FR", "1000"),
        ("KB", "99.95"),
    ],
)
def test_invalid_arguments(code, value):
    with pytest.raises(ValueError):
        encode(code, value)


def test_units_terminators_and_exact_domain():
    assert encode("FR", 300, unit="MZ") == b"FR300MZ"
    assert encode("CL", "98.5", terminator="%") == b"CL98.5%"
    assert encode("DY", "98.5", terminator="PCT") == b"DY98.5PCT"
    with pytest.raises(ValueError):
        encode("FR", 1, unit="GZ;PR")
    with pytest.raises(ValueError):
        encode("KB", 99, terminator="ENPR")


def test_inventory_reconciliation_and_complete_test_enumeration():
    text = (Path(__file__).parents[1] / "docs/inventory/COMMANDS.md").read_text()
    expected = dict(re.findall(r"### (C\d+)\n\n`([^`]+)`", text))
    assert {spec.id: code for code, spec in COMMANDS.items()} == expected
    assert len(expected) == 118
    assert set(ARGUMENTS) | set(RF_CASES) | set(LITERALS) == {
        c for c, spec in COMMANDS.items() if not spec.deferred
    }
